def has_close_elements(numbers: List[float], threshold: float) -> bool:
    # Validate inputs
    if not isinstance(numbers, list):
        raise TypeError("numbers must be a list")
    if not isinstance(threshold, (int, float)):
        raise TypeError("threshold must be a number")
    if threshold <= 0:
        return False
    n = len(numbers)
    if n < 2:
        return False
    # Validate elements
    for x in numbers:
        if not isinstance(x, (int, float)):
            raise TypeError("all elements in numbers must be numeric")
    # Sort
    sorted_nums = sorted(numbers)
    for i in range(1, n):
        if abs(sorted_nums[i] - sorted_nums[i-1]) < threshold:
            return True
    return False

def find_topmost_carpet(n, carpets, point) -> int:
    """
    Finds the topmost carpet covering a given point on the coordinate plane.

    Args:
        n (int): The total number of carpets.
        carpets (list of tuples): A list containing n tuples, each representing a carpet's information.
                                  Each tuple contains four integers (a, b, g, k) where (a, b) is the
                                  coordinates of the bottom-left corner of the carpet and (g, k) are
                                  the lengths of the carpet along the x and y axis respectively.
        point (tuple): A tuple containing two integers (x, y), the coordinates of the point to check.

    Returns:
        int: The number of the topmost carpet covering the point (x, y), or -1 if no carpet covers it.
    """
    # Basic validation
    try:
        if not isinstance(n, int) or n <= 0:
            return -1
        if not isinstance(carpets, list) or len(carpets) < n:
            return -1
        if not isinstance(point, (tuple, list)) or len(point) != 2:
            return -1
        x, y = point
        if not (isinstance(x, int) and isinstance(y, int)):
            return -1
    except Exception:
        return -1

    # Iterate from topmost (last) to bottom
    for idx in range(n - 1, -1, -1):
        try:
            a, b, g, k = carpets[idx]
            if not all(isinstance(v, int) for v in (a, b, g, k)):
                continue
            if a <= x <= a + g and b <= y <= b + k:
                return idx + 1  # 1-based numbering
        except Exception:
            continue
    return -1

def max_product(num_str: str, N: int, K: int) -> int:
    """
    Return the maximum product obtainable by inserting K multiplication signs into the
    number string `num_str` of length N. The string consists only of decimal digits.
    If the input is invalid (e.g., K > N-1, negative K, or N does not match the length
    of num_str), the function returns 0.
    """
    # Validate input
    if not num_str or N <= 0 or K < 0:
        return 0
    if N != len(num_str):
        return 0
    if K > N - 1:
        return 0

    # Special case: no multiplication signs
    if K == 0:
        try:
            return int(num_str)
        except ValueError:
            return 0

    # Precompute integer values of all substrings to avoid repeated conversions
    # substr_val[i][j] will hold int(num_str[i:j]) for 0 <= i < j <= N
    substr_val = [[0] * (N + 1) for _ in range(N + 1)]
    for i in range(N):
        val = 0
        for j in range(i + 1, N + 1):
            val = val * 10 + (ord(num_str[j - 1]) - 48)
            substr_val[i][j] = val

    # DP table: dp[i][k] = max product for prefix of length i with k multiplications
    dp = [[0] * (K + 1) for _ in range(N + 1)]

    # Base case: no multiplications
    for i in range(1, N + 1):
        dp[i][0] = substr_val[0][i]

    # Fill DP
    for k in range(1, K + 1):
        # Need at least k+1 digits to place k multiplications
        for i in range(k + 1, N + 1):
            max_prod = 0
            # Split point j: last part starts at j, so previous part ends at j
            # j ranges from k to i-1 (inclusive)
            for j in range(k, i):
                prod = dp[j][k - 1] * substr_val[j][i]
                if prod > max_prod:
                    max_prod = prod
            dp[i][k] = max_prod

    return dp[N][K] if K <= N - 1 else 0

def polynomial_to_string(n: int, coeffs: list) -> str:
    """
    Converts a list of polynomial coefficients into a formatted string representation.

    Args:
        n (int): The highest degree of the polynomial.
        coeffs (List[int]): A list of coefficients, starting with the coefficient of the highest degree term.

    Returns:
        str: The string representation of the polynomial.

    Raises:
        TypeError: If inputs are of incorrect type.
        ValueError: If n is negative or the length of coeffs does not match n+1.
    """
    # Basic input validation
    if not isinstance(n, int):
        raise TypeError(f"Expected n to be int, got {type(n).__name__}")
    if n < 0:
        raise ValueError(f"Degree n must be non‑negative, got {n}")
    if not isinstance(coeffs, list):
        raise TypeError(f"Expected coeffs to be list, got {type(coeffs).__name__}")
    if len(coeffs) != n + 1:
        raise ValueError(f"Length of coeffs ({len(coeffs)}) does not match expected {n + 1}")

    terms = []
    first_term = True

    for idx, coeff in enumerate(coeffs):
        degree = n - idx
        if not isinstance(coeff, int):
            raise TypeError(f"Coefficient at index {idx} is not an int: {coeff!r}")

        if coeff == 0:
            continue

        # Determine sign
        if first_term:
            sign = '-' if coeff < 0 else ''
        else:
            sign = '+' if coeff > 0 else '-'

        abs_coeff = abs(coeff)

        # Determine coefficient string
        if abs_coeff == 1 and degree > 0:
            coeff_str = ''
        else:
            coeff_str = str(abs_coeff)

        # Determine variable part
        if degree > 1:
            var_str = f'x^{degree}'
        elif degree == 1:
            var_str = 'x'
        else:
            var_str = ''

        term = f"{sign}{coeff_str}{var_str}"
        terms.append(term)
        first_term = False

    if not terms:
        return '0'

    return ''.join(terms)

def count_sequences(n: int, last: int, memo: dict) -> int:
    # Validate inputs
    if not isinstance(n, int) or not isinstance(last, int):
        raise TypeError("n and last must be integers")
    if n <= 0 or last <= 0:
        raise ValueError("n and last must be positive integers")
    if not isinstance(memo, dict):
        raise TypeError("memo must be a dictionary")
    # Use memoization
    if last in memo:
        return memo[last]
    # Base case: if last <= 1, no further numbers can be appended
    if last <= 1:
        memo[last] = 1
        return 1
    # Count sequences
    total = 1  # sequence that stops at last
    max_next = last // 2
    for k in range(1, max_next + 1):
        total += count_sequences(n, k, memo)
    memo[last] = total
    return total

def string_transformation(A: str, B: str, rules: list) -> Union[int, str]:
    """
    Perform string transformation from A to B using a set of transformation rules.
    Uses BFS up to a maximum of 10 steps. Returns the minimum number of steps
    required to transform A into B, or "NO ANSWER!" if impossible within 10 steps.
    """
    # Basic input validation
    if not isinstance(A, str) or not isinstance(B, str):
        raise TypeError("A and B must be strings.")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples.")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("Each rule must be a tuple of two strings.")
        if not isinstance(rule[0], str) or not isinstance(rule[1], str):
            raise ValueError("Rule elements must be strings.")

    # If already equal
    if A == B:
        return 0

    from collections import deque

    max_depth = 10
    visited = set()
    queue = deque()
    queue.append((A, 0))
    visited.add(A)

    while queue:
        current, depth = queue.popleft()
        if depth >= max_depth:
            continue  # do not expand further

        for src, tgt in rules:
            # Skip invalid or useless rules
            if not src or src == tgt:
                continue
            start = 0
            while True:
                idx = current.find(src, start)
                if idx == -1:
                    break
                new_str = current[:idx] + tgt + current[idx + len(src):]
                if new_str == B:
                    return depth + 1
                if new_str not in visited:
                    visited.add(new_str)
                    queue.append((new_str, depth + 1))
                start = idx + 1  # allow overlapping matches

    return "NO ANSWER!"

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to determine if a statement is about a day of the week
    def is_day_statement(stmt: str) -> bool:
        upper = stmt.upper()
        return any(day in upper for day in days_of_week)

    for participant, stmts in statements.items():
        for stmt in stmts:
            # Skip statements that mention a day of the week
            if is_day_statement(stmt):
                continue

            # Remove trailing period and strip whitespace
            stmt_clean = stmt.strip()
            if stmt_clean.endswith('.'):
                stmt_clean = stmt_clean[:-1]
            stmt_lower = stmt_clean.lower()

            # Determine subject of the statement
            if stmt_lower.startswith('i '):
                subject = participant
            else:
                # Subject is the first word before any space
                subject = stmt_clean.split()[0].strip('.,!?')

            # Determine if the statement claims guilt or innocence
            if 'not guilty' in stmt_lower:
                claimed_guilty = False
            elif 'guilty' in stmt_lower:
                claimed_guilty = True
            else:
                # Statement does not concern guilt; ignore it
                continue

            # Evaluate truth of the statement
            is_subject_guilty = (subject == scenario)
            truth = (is_subject_guilty == claimed_guilty)

            # Check consistency with liar status
            if participant in liar_count:
                if truth:
                    return False  # liar cannot tell the truth
            else:
                if not truth:
                    return False  # truth-teller cannot lie

    return

def max_herb_value(T: int, M: int, herbs: list) -> int:
    """
    Calculate the maximum total value of herbs that can be picked within a given time limit.

    This function solves a variation of the 0/1 knapsack problem where the goal is to maximize
    the total value of herbs picked without exceeding the time limit. Each herb can be picked
    at most once and has an associated time cost and value.

    Args:
    - T (int): The total time available for picking herbs.
    - M (int): The number of different herbs in the cave.
    - herbs (List[Tuple[int, int]]): A list of tuples, where each tuple contains two integers
      representing the time required to pick the herb and the herb's value, respectively.

    Returns:
    - int: The maximum total value of herbs that can be picked within the time limit.
    """
    # Basic input validation
    if not isinstance(T, int) or not isinstance(M, int):
        raise TypeError("T and M must be integers")
    if T < 0 or M < 0:
        return 0
    if not isinstance(herbs, list):
        raise TypeError("herbs must be a list of tuples")
    if len(herbs) != M:
        raise ValueError("Length of herbs list does not match M")
    for item in herbs:
        if not (isinstance(item, tuple) and len(item) == 2):
            raise TypeError("Each herb must be a tuple of two integers")
        if not (isinstance(item[0], int) and isinstance(item[1], int)):
            raise TypeError("Herb time and value must be integers")
        if item[0] < 0 or item[1] < 0:
            raise ValueError("Herb time and value must be non-negative")

    if T == 0 or M == 0:
        return 0

    # Initialize DP array: dp[t] = max value achievable with time t
    dp = [0] * (T + 1)

    for time_cost, value in herbs:
        if time_cost > T:
            # This herb cannot be taken within the time limit
            continue
        # Traverse backwards to avoid using the same herb multiple times
        for t in range(T, time_cost - 1, -1):
            new_val = dp[t - time_cost] + value
            if new_val > dp[t]:
                dp[t] = new_val

    return max(dp)

def sort_students(student_scores):
    """
    Sorts a list of students based on their scores. The students are sorted primarily by their total score (descending),
    then by their Chinese score (descending), and finally by their student number (ascending) in case of a tie.

    Args:
        student_scores (list): A list of tuples, where each tuple consists of (student_number, total_score, Chinese_score).

    Returns:
        list: A list of tuples sorted according to the above rules.

    Raises:
        TypeError: If student_scores is not a list.
        ValueError: If any element is not a tuple/list of length 3 or contains non-numeric values.
    """
    if not isinstance(student_scores, list):
        raise TypeError("student_scores must be a list")

    # Validate each entry
    for idx, entry in enumerate(student_scores):
        if not isinstance(entry, (tuple, list)):
            raise ValueError(f"Entry at index {idx} is not a tuple or list")
        if len(entry) != 3:
            raise ValueError(f"Entry at index {idx} does not contain exactly 3 elements")
        student_number, total_score, chinese_score = entry
        if not isinstance(student_number, (int, float)):
            raise ValueError(f"Student number at index {idx} is not numeric")
        if not isinstance(total_score, (int, float)):
            raise ValueError(f"Total score at index {idx} is not numeric")
        if not isinstance(chinese_score, (int, float)):
            raise ValueError(f"Chinese score at index {idx} is not numeric")

    # Perform sorting
    try:
        sorted_list = sorted(
            student_scores,
            key=lambda x: (-x[1], -x[2], x[0])
        )
    except Exception as e:
        raise RuntimeError(f"Error during sorting: {e}")

    return sorted_list
